437			\item $\mathsf{Constraint}_i$: content $\omega$ as above; answer $(\alpha_{v_1}, \alpha_{v_2}, \alpha_{v_3}) \in \F_2^3$, indexed by the variable indices $(v_1,v_2,v_3)$ of $\mathsf{Constraint}_i$.
438			\item $\mathsf{Variable}_j$: content $\omega$ as above; answer an element of $\F_2$.
439			\item $(\mathsf{Pauli},W)$: content $0$; answer an element of $\F_q^M$.
