517			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
518		\end{enumerate}
519		The game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
520	\end{definition}
