1886	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
1887		\lean{MIPStarRE.QPBT.IsTypedCondLinearFamily}
1888		\uses{def:cl-func}
1889		Let $\mathcal T$ be a set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$. Finiteness of $\mathcal T$ is not needed for this pointwise condition, so the definition applies to an arbitrary type set. A finite type set is required from Definition~\ref{def:graph-distribution} onwards, where $\mathcal T$ indexes a distribution. The source states the definition for a finite type set, and every type set occurring below is finite.
1890	\end{definition}
1891	
1892	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
1893	% normalization 1/(2m-k) below is undefined. The source
1894	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
1895	\begin{definition}[Graph distribution]\label{def:graph-distribution}
1896		\lean{MIPStarRE.QPBT.graphDistribution}
1897		\leanok
1898		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
1899		\[
1900			\mu_G(u, v) =
1901			\begin{cases}
1902				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
1903				0 & \text{otherwise}\,.
1904			\end{cases}
1905		\]
1906		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
1907	\end{definition}
