1930	\begin{definition}[Typed conditionally linear distributions]\label{def:typed-cl-distributions}
1931		\lean{MIPStarRE.QPBT.typedCLDistribution}
1932		\uses{def:typed-cl-functions, def:graph-distribution, def:cl-dist}
